-- GENERATED by scripts/export_load_sql.py from etl/dimensions/spec.py: do not edit by hand; change
-- the spec and re-export (make test fails while this file and the loader differ).
--
-- The pipeline runs these statements through etl/dimensions/load.py (python etl/dimensions/run.py),
-- in this order, one transaction per dimension, and adds what plain SQL cannot:
--   * refuses a source with a natural key twice or missing (the step fails, nothing changes);
--   * the SCD2 versions (US-6.2, US-6.3): from each member's history (_dim_hist) Python plans the
--     versions it should have and, per new version, closes the current one and opens the next:
--        UPDATE lue_dw.<dim> SET effective_to = <change date>, is_current = FALSE, batch_id, loaded_at
--          WHERE <key> = <current key>;
--        INSERT INTO lue_dw.<dim> (<natural key, other columns>, <type 2 columns>, effective_from,
--          effective_to, is_current, ...) SELECT ..., <new type 2 values>, <change date>,
--          DATE '9999-12-31', TRUE, ... FROM lue_dw.<dim> WHERE <key> = <current key>;
--     (marked below where it runs; run by hand, this file loads new members with their first state)
--   * the counts in lue_audit.etl_run_log, the lineage, and fresh statistics (ANALYZE).
-- Run by hand on a warehouse with staging loaded (it is one transaction):
--   psql -d lue_warehouse -v ON_ERROR_STOP=1 -f sql/30_dimensions/02_dimension_loads.sql
-- The static dimensions (dim_date, payment method, charge type, lease event type, request flags)
-- are loaded by sql/30_dimensions/01_reference_dimensions.sql (US-1.4).

BEGIN;
SELECT set_config('lue.run_id', nextval('lue_audit.seq_run_id')::text, false),
       set_config('lue.loaded_at', date_trunc('second', localtimestamp)::text, false);

-- ------------------------------------------------------------------------------------------------
-- dim_date: the holiday and Ramadan flags from the S2 register (US-6.4)
-- ------------------------------------------------------------------------------------------------
UPDATE lue_dw.dim_date d
    SET is_public_holiday = coalesce(h.is_public_holiday, FALSE), holiday_name = h.holiday_name,
        is_ramadan = coalesce(h.is_ramadan, FALSE)
    FROM lue_dw.dim_date x LEFT JOIN lue_staging.stg_holiday h ON h.holiday_date = x.full_date
    WHERE d.date_key = x.date_key AND x.date_key > 0
      AND (d.is_public_holiday, d.holiday_name, d.is_ramadan) IS DISTINCT FROM
          (coalesce(h.is_public_holiday, FALSE), h.holiday_name, coalesce(h.is_ramadan, FALSE));

-- ------------------------------------------------------------------------------------------------
-- dim_owner (US-6.4): natural key owner_code; surrogate key owner_key (identity); Type 1
-- ------------------------------------------------------------------------------------------------
-- Type 1 (overwrite): owner_name, owner_type, portfolio_size_band
-- the source: one row per natural key with its current values (staging)
CREATE TEMP TABLE _dim_src ON COMMIT DROP AS
        SELECT o.owner_code, coalesce(o.owner_name, 'Unknown') AS owner_name,
               coalesce(o.owner_type, 'Unknown') AS owner_type,
               CASE count(s.unit_no) WHEN 0 THEN 'None' WHEN 1 THEN '1 unit'
                    ELSE CASE WHEN count(s.unit_no) <= 5 THEN '2–5 units' ELSE '6+ units' END END AS portfolio_size_band,
               o.source_system
        FROM lue_staging.stg_owner o
        LEFT JOIN lue_staging.stg_ownership s ON s.owner_code = o.owner_code
             AND s.valid_from <= current_date AND (s.valid_to IS NULL OR s.valid_to >= current_date)
        GROUP BY o.owner_code, o.owner_name, o.owner_type, o.source_system;
-- new members (US-6.1)
INSERT INTO lue_dw.dim_owner (owner_code, owner_name, owner_type, portfolio_size_band, source_system, batch_id, loaded_at) SELECT s.owner_code, s.owner_name, s.owner_type, s.portfolio_size_band, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _dim_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.dim_owner x WHERE x.owner_code = s.owner_code) ORDER BY s.owner_code;
-- Type 1: overwrite in place on every version where a value differs
UPDATE lue_dw.dim_owner x SET owner_name = s.owner_name, owner_type = s.owner_type, portfolio_size_band = s.portfolio_size_band, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _dim_src s WHERE x.owner_code = s.owner_code AND x.owner_key > 0 AND (x.owner_name, x.owner_type, x.portfolio_size_band) IS DISTINCT FROM (s.owner_name, s.owner_type, s.portfolio_size_band);
