INSERT INTO lue_dw.dim_maintenance_category (subcategory_code, subcategory_name, category_name, default_sla_hours, effective_from, effective_to, is_current, source_system, batch_id, loaded_at) SELECT s.subcategory_code, s.subcategory_name, s.category_name, coalesce(h.default_sla_hours, s.default_sla_hours), DATE '1900-01-01', DATE '9999-12-31', TRUE, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _dim_src s LEFT JOIN (SELECT DISTINCT ON (h.subcategory_code) h.subcategory_code, h.default_sla_hours FROM _dim_hist h ORDER BY h.subcategory_code, h.change_date NULLS FIRST, h.seq) h ON h.subcategory_code = s.subcategory_code WHERE NOT EXISTS (SELECT 1 FROM lue_dw.dim_maintenance_category x WHERE x.subcategory_code = s.subcategory_code) ORDER BY s.subcategory_code;
