-- the source: one row per natural key with its current values (staging)
CREATE TEMP TABLE _dim_src ON COMMIT DROP AS
        SELECT w.city, w.weather_date, coalesce(w.rainfall_mm, 0) AS rainfall_mm,
               CASE WHEN w.rainfall_mm IS NULL THEN 'Unknown' WHEN w.rainfall_mm < 1 THEN 'None'
                    WHEN w.rainfall_mm <= 10 THEN 'Light' ELSE 'Heavy' END AS rain_band,
               coalesce(w.max_temp_c, 0) AS max_temp_c,
               CASE WHEN w.max_temp_c IS NULL THEN 'Unknown' WHEN w.max_temp_c < 35 THEN 'Mild'
                    WHEN w.max_temp_c <= 40 THEN 'Hot' ELSE 'Extreme' END AS heat_band,
               w.source_system
        FROM lue_staging.stg_weather w;
-- new members (US-6.1)
INSERT INTO lue_dw.dim_weather (city, weather_date, rainfall_mm, rain_band, max_temp_c, heat_band, source_system, batch_id, loaded_at) SELECT s.city, s.weather_date, s.rainfall_mm, s.rain_band, s.max_temp_c, s.heat_band, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _dim_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.dim_weather x WHERE x.city = s.city AND x.weather_date = s.weather_date) ORDER BY s.city, s.weather_date;
