-- ------------------------------------------------------------------------------------------------
-- dim_unit (US-6.3): natural key unit_nk; surrogate key unit_key (identity); SCD Type 2
-- ------------------------------------------------------------------------------------------------
-- Type 1 (overwrite): bedrooms, area_sqft, building_name, building_class, building_age_band, locality, city, region
-- Type 2 (history):  unit_type, furnished_flag
-- Type 0 (fixed):    building_code, unit_no, floor_no
-- the source: one row per natural key with its current values (staging)
CREATE TEMP TABLE _dim_src ON COMMIT DROP AS
        SELECT u.building_code || '-' || u.unit_no AS unit_nk, u.building_code, u.unit_no,
               coalesce(u.unit_type, 'Unknown') AS unit_type, coalesce(u.bedrooms, 0) AS bedrooms,
               coalesce(u.area_sqft, 0) AS area_sqft, coalesce(u.furnished, FALSE) AS furnished_flag,
               coalesce(u.floor_no, 0) AS floor_no, coalesce(b.building_name, 'Unknown') AS building_name,
               coalesce(b.building_class, '?') AS building_class, CASE WHEN b.year_built IS NULL THEN 'Unknown' WHEN extract(year FROM current_date)::int - b.year_built <= 5 THEN '0–5 yrs' WHEN extract(year FROM current_date)::int - b.year_built <= 15 THEN '6–15 yrs' ELSE '16+ yrs' END AS building_age_band,
               coalesce(b.locality, 'Unknown') AS locality, coalesce(b.city, 'Unknown') AS city,
               coalesce(b.region, 'Unknown') AS region, u.source_system
        FROM lue_staging.stg_unit u LEFT JOIN lue_staging.stg_building b USING (building_code);
-- its history: every known state with the date it took effect, oldest first
CREATE TEMP TABLE _dim_hist ON COMMIT DROP AS
    SELECT upper(lue_staging.clean_text(b.building_code)) || '-' || lue_staging.clean_text(b.unit_no) AS unit_nk,
           coalesce(lue_staging.std('unit_type', b.unit_type), 'Unknown') AS unit_type,
           coalesce(lower(lue_staging.clean_text(b.furnished))::boolean, FALSE) AS furnished_flag,
           (lue_audit.try_timestamp(b.updated_at))::date AS change_date,
           row_number() OVER (ORDER BY lue_audit.try_timestamp(b.updated_at), b.loaded_at, b.row_id) AS seq
    FROM lue_staging.brz_unit b WHERE b.batch_id IN (SELECT batch_id FROM lue_audit.dq_batch) AND NOT EXISTS (SELECT 1 FROM lue_audit.dq_result r WHERE r.source_table = 'brz_unit' AND r.row_id = b.row_id AND r.severity = 'reject');
-- new members (US-6.1), with their oldest known state, valid from 1900-01-01
INSERT INTO lue_dw.dim_unit (unit_nk, building_code, unit_no, unit_type, bedrooms, area_sqft, furnished_flag, floor_no, building_name, building_class, building_age_band, locality, city, region, effective_from, effective_to, is_current, source_system, batch_id, loaded_at) SELECT s.unit_nk, s.building_code, s.unit_no, coalesce(h.unit_type, s.unit_type), s.bedrooms, s.area_sqft, coalesce(h.furnished_flag, s.furnished_flag), s.floor_no, s.building_name, s.building_class, s.building_age_band, s.locality, s.city, s.region, DATE '1900-01-01', DATE '9999-12-31', TRUE, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _dim_src s LEFT JOIN (SELECT DISTINCT ON (h.unit_nk) h.unit_nk, h.unit_type, h.furnished_flag FROM _dim_hist h ORDER BY h.unit_nk, h.change_date NULLS FIRST, h.seq) h ON h.unit_nk = s.unit_nk WHERE NOT EXISTS (SELECT 1 FROM lue_dw.dim_unit x WHERE x.unit_nk = s.unit_nk) ORDER BY s.unit_nk;
-- SCD2 versions from _dim_hist: etl/dimensions/load.py apply_scd2 (see the header); Type 2: unit_type, furnished_flag
-- Type 1: overwrite in place on every version where a value differs
UPDATE lue_dw.dim_unit x SET bedrooms = s.bedrooms, area_sqft = s.area_sqft, building_name = s.building_name, building_class = s.building_class, building_age_band = s.building_age_band, locality = s.locality, city = s.city, region = s.region, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _dim_src s WHERE x.unit_nk = s.unit_nk AND x.unit_key > 0 AND (x.bedrooms, x.area_sqft, x.building_name, x.building_class, x.building_age_band, x.locality, x.city, x.region) IS DISTINCT FROM (s.bedrooms, s.area_sqft, s.building_name, s.building_class, s.building_age_band, s.locality, s.city, s.region);
DROP TABLE _dim_src;
DROP TABLE _dim_hist;

-- ------------------------------------------------------------------------------------------------
-- dim_tenant (US-6.1): natural key tenant_code; surrogate key tenant_key (identity); SCD Type 2, inferred members
-- ------------------------------------------------------------------------------------------------
-- Type 1 (overwrite): tenant_name, contact_channel
-- Type 2 (history):  tenant_type, employer_sector
-- the source: one row per natural key with its current values (staging)
CREATE TEMP TABLE _dim_src ON COMMIT DROP AS
        SELECT t.tenant_code,
               coalesce(t.tenant_name, 'Unknown') AS tenant_name,
               coalesce(t.tenant_type, 'Unknown') AS tenant_type,
               coalesce(t.employer_sector, 'Unknown') AS employer_sector,
               coalesce(t.contact_channel, 'Unknown') AS contact_channel,
               t.source_system
        FROM lue_staging.stg_tenant t;
-- its history: every known state with the date it took effect, oldest first
CREATE TEMP TABLE _dim_hist ON COMMIT DROP AS
    SELECT upper(lue_staging.clean_text(b.tenant_code)) AS tenant_code,
           coalesce(lue_staging.std('tenant_type', b.tenant_type), 'Unknown') AS tenant_type,
           coalesce(lue_staging.std('employer_sector', b.employer_sector), lue_staging.clean_text(b.employer_sector), 'Unknown') AS employer_sector,
           (lue_audit.try_timestamp(b.updated_at))::date AS change_date,
           row_number() OVER (ORDER BY lue_audit.try_timestamp(b.updated_at), b.loaded_at, b.row_id) AS seq
    FROM lue_staging.brz_tenant b WHERE b.batch_id IN (SELECT batch_id FROM lue_audit.dq_batch) AND NOT EXISTS (SELECT 1 FROM lue_audit.dq_result r WHERE r.source_table = 'brz_tenant' AND r.row_id = b.row_id AND r.severity = 'reject');
-- new members (US-6.1), with their oldest known state, valid from 1900-01-01
INSERT INTO lue_dw.dim_tenant (tenant_code, tenant_name, tenant_type, employer_sector, contact_channel, is_inferred, effective_from, effective_to, is_current, source_system, batch_id, loaded_at) SELECT s.tenant_code, s.tenant_name, coalesce(h.tenant_type, s.tenant_type), coalesce(h.employer_sector, s.employer_sector), s.contact_channel, FALSE, DATE '1900-01-01', DATE '9999-12-31', TRUE, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _dim_src s LEFT JOIN (SELECT DISTINCT ON (h.tenant_code) h.tenant_code, h.tenant_type, h.employer_sector FROM _dim_hist h ORDER BY h.tenant_code, h.change_date NULLS FIRST, h.seq) h ON h.tenant_code = s.tenant_code WHERE NOT EXISTS (SELECT 1 FROM lue_dw.dim_tenant x WHERE x.tenant_code = s.tenant_code) ORDER BY s.tenant_code;
-- inferred members whose record has arrived: real values, is_inferred FALSE (US-6.5)
UPDATE lue_dw.dim_tenant x SET tenant_name = s.tenant_name, tenant_type = coalesce(h.tenant_type, s.tenant_type), employer_sector = coalesce(h.employer_sector, s.employer_sector), contact_channel = s.contact_channel, is_inferred = FALSE, source_system = s.source_system, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _dim_src s LEFT JOIN (SELECT DISTINCT ON (h.tenant_code) h.tenant_code, h.tenant_type, h.employer_sector FROM _dim_hist h ORDER BY h.tenant_code, h.change_date NULLS FIRST, h.seq) h ON h.tenant_code = s.tenant_code WHERE x.tenant_code = s.tenant_code AND x.is_inferred AND x.tenant_key > 0;
-- SCD2 versions from _dim_hist: etl/dimensions/load.py apply_scd2 (see the header); Type 2: tenant_type, employer_sector
-- Type 1: overwrite in place on every version where a value differs
UPDATE lue_dw.dim_tenant x SET tenant_name = s.tenant_name, contact_channel = s.contact_channel, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _dim_src s WHERE x.tenant_code = s.tenant_code AND x.tenant_key > 0 AND (x.tenant_name, x.contact_channel) IS DISTINCT FROM (s.tenant_name, s.contact_channel);
-- inferred members for natural keys staging references but no member has yet (US-6.5)
INSERT INTO lue_dw.dim_tenant (tenant_code, tenant_name, tenant_type, employer_sector, contact_channel, is_inferred, effective_from, effective_to, is_current, source_system, batch_id, loaded_at) SELECT r.ref, u.tenant_name, u.tenant_type, u.employer_sector, u.contact_channel, TRUE, DATE '1900-01-01', DATE '9999-12-31', TRUE, 'INFERRED', current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM (SELECT DISTINCT x.tenant_code AS ref FROM (
        SELECT tenant_code FROM lue_staging.stg_lease WHERE tenant_code IS NOT NULL
        UNION SELECT tenant_code FROM lue_staging.stg_payment WHERE tenant_code IS NOT NULL) x WHERE x.tenant_code IS NOT NULL) r CROSS JOIN (SELECT * FROM lue_dw.dim_tenant WHERE tenant_key = -1) u WHERE NOT EXISTS (SELECT 1 FROM lue_dw.dim_tenant m WHERE m.tenant_code = r.ref) ORDER BY r.ref;
