        FROM lue_staging.stg_lease l;
-- new members (US-6.1)
INSERT INTO lue_dw.dim_lease (lease_number, lease_type, start_date, end_date, term_months, original_monthly_rent, rent_review_type, previous_lease_number, source_system, batch_id, loaded_at) SELECT s.lease_number, s.lease_type, s.start_date, s.end_date, s.term_months, s.original_monthly_rent, s.rent_review_type, s.previous_lease_number, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _dim_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.dim_lease x WHERE x.lease_number = s.lease_number) ORDER BY s.lease_number;
DROP TABLE _dim_src;

COMMIT;
